if (Test-Path -LiteralPath $destination) {
    if (-not $Force) { throw "Destination already exists: $destination. Re-run with -Force or choose a different -DestinationPath." }
    Remove-Item -LiteralPath $destination -Recurse -Force
}
New-Item -ItemType Directory -Force -Path $destination | Out-Null
$tempZip = Join-Path ([IO.Path]::GetTempPath()) ('cdt-workflow-' + [Guid]::NewGuid().ToString('N') + '.zip')
try {
    $cleanBase64 = $base64 -replace '\s', ''
    [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($cleanBase64))
    $actualSha256 = (Get-FileHash -LiteralPath $tempZip -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actualSha256 -ne $expectedSha256) { throw "Bundle SHA-256 mismatch. Expected $expectedSha256 but got $actualSha256." }
    Expand-Archive -LiteralPath $tempZip -DestinationPath $destination -Force
    $files = @(Get-ChildItem -LiteralPath $destination -Recurse -File)
    if ($files.Count -ne $expectedFileCount) { throw "Restored file count mismatch. Expected $expectedFileCount but got $($files.Count)." }
    Write-Host "Restored cdt-workflow bundle from commit $sourceCommit"
    Write-Host "Destination: $destination"
    Write-Host "Files restored: $($files.Count)"
    Write-Host "ZIP SHA-256: $actualSha256"
}
finally {
    if (Test-Path -LiteralPath $tempZip) { Remove-Item -LiteralPath $tempZip -Force }
}
